testo:
{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run():
	var direction := Vector2(3.0, 4.0).normalized()
	var speed: float = 100.0
	return direction * speed
",
   "domanda": "Che Vector2 restituisce run()?",
   "spiegazione": "`Vector2(3.0, 4.0).normalized()` calcola la direzione normalizzata pari a `Vector2(0.6, 0.8)`. Moltiplicandola per la velocità di 100.0 si ottiene `Vector2(60, 80)`."
  },
  {
   "codice": "extends RefCounted


func run():
	var pos_x: float = 850.0
	var screen_width: float = 800.0
	return clampf(pos_x, 0.0, screen_width)
",
   "domanda": "Quanto vale il numero restituito da run()?",
   "spiegazione": "`clampf` limita il valore tra un minimo (0.0) e un massimo (800.0). Poiché 850.0 supera il massimo consentito, viene bloccato esattamente a 800.0."
  },
  {
   "codice": "extends RefCounted


func run():
	var direction := Vector2.ZERO
	if direction != Vector2.ZERO:
		direction = direction.normalized()
	return direction
",
   "domanda": "Quanto vale il Vector2 restituito da run()?",
   "spiegazione": "`direction` parte come `Vector2.ZERO`. La condizione `direction != Vector2.ZERO` risulta falsa, quindi il blocco `if` viene saltato e la funzione restituisce `(0, 0)`."
  },
  {
   "codice": "extends RefCounted


func run():
	var pos_y: float = -10.0
	return clampf(pos_y, 0.0, 600.0)
",
   "domanda": "Quanto vale il numero restituito da run()?",
   "spiegazione": "`clampf` verifica se il valore rientra tra 0.0 e 600.0. Poiché -10.0 è inferiore al minimo, viene riportato al limite inferiore, cioè 0.0."
  },
  {
   "codice": "extends RefCounted


func run():
	var pos_y: float = 610.0
	if pos_y > 600.0:
		pos_y = -30.0
	return pos_y
",
   "domanda": "Quanto vale pos_y alla fine?",
   "spiegazione": "`pos_y` vale 610.0, che è maggiore di 600.0. La condizione è vera e la posizione viene resettata a -30.0, come succede ai meteoriti quando escono dallo schermo in basso."
  }
 ]
}
